-- Questões originais de estudo: Deitel e Deitel, Java: como programar, 10ª edição.
-- Tradução brasileira do PDF fornecido: Pearson Education do Brasil, 2017.
-- Contexto dos recursos: Java SE 8. Não são questões oficiais nem exercícios transcritos.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens entram como rascunhos. Revise antes de publicar.
-- Páginas são do arquivo PDF, não da numeração impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve registros existentes.
-- Capítulo 5: Instruções de controle: parte 2; operadores lógicos — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('66cd46de-7421-5cf1-a4e9-09293f8cbc4d', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Linguagem de Programação', 'Fácil', 'Um loop controlado por contador precisa, entre outros elementos, de:', '["Apenas um import.","Inicialização, teste e atualização do controle.","Um switch obrigatório.","Somente um comentário.","Um construtor obrigatório."]'::jsonb, 1, 'Sem atualização adequada, a condição pode nunca deixar de valer.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.2, páginas 155 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b55e492f-2c92-5189-8378-c3b40998f5f8', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Linguagem de Programação', 'Fácil', 'Quantas vezes executa `for(int i=0;i<4;i++)` sem desvios?', '["4.","1.","3.","5.","0."]'::jsonb, 0, 'O corpo usa os valores 0, 1, 2 e 3.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.3, páginas 156–159 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1834b420-da7f-50c6-b90e-f73d15097172', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Linguagem de Programação', 'Fácil', 'Qual valor de s após `int s=0; for(int i=1;i<=4;i++) s+=i;`?', '["4.","0.","15.","6.","10."]'::jsonb, 4, 'A soma é 1+2+3+4.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.3, páginas 156–159 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f247f321-ec01-5404-9270-a52009e3898d', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Linguagem de Programação', 'Médio', 'Uma variável i declarada no cabeçalho de for está disponível após o loop?', '["Sim, sempre globalmente.","Somente em main.","Somente se public.","Não, fora daquele escopo.","Sim, com valor zero."]'::jsonb, 3, 'A declaração pertence ao escopo da instrução for.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.3, páginas 156–159 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2e3d7fc8-76e9-50b2-b833-47f61f2c7931', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Linguagem de Programação', 'Médio', 'Quais valores percorre `for(int i=2;i<=8;i+=2)`?', '["0, 2, 4 e 6.","2, 4, 6 e 8.","4, 6 e 8.","2 e 8 apenas.","2, 3, 4, 5, 6, 7 e 8."]'::jsonb, 1, 'A atualização acrescenta dois após cada execução.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.4, páginas 160–162 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0016b9f0-1b2b-50a0-9ae5-62874ca3c110', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Linguagem de Programação', 'Médio', 'Omitir a condição em `for(;;)` significa:', '["Zero iterações.","Uma única iteração.","Condição de continuação verdadeira.","Condição sempre falsa.","Erro obrigatório de compilação."]'::jsonb, 2, 'O término exige algum desvio ou outro encerramento apropriado.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.3, páginas 156–159 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f4dd4df8-ad73-5f33-9222-f633cb859361', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Linguagem de Programação', 'Médio', 'Qual loop testa a condição após executar o corpo?', '["for tradicional.","while.","do…while.","Nenhum.","for aprimorado."]'::jsonb, 2, 'Do…while executa ao menos uma vez em seu fluxo normal.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.5, páginas 163–164 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('060dacc3-423e-5952-8a47-683d69d91fd5', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Linguagem de Programação', 'Médio', 'Após `int x=5; do{x++;}while(x<3);`, qual é x?', '["5.","6.","Erro.","3.","4."]'::jsonb, 1, 'O corpo executa uma vez antes do teste falso.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.5, páginas 163–164 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('791981cf-11cd-5013-b15a-686c1e72b363', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Linguagem de Programação', 'Médio', 'Sem break, um case de switch tradicional pode:', '["Reiniciar o switch.","Continuar pelos comandos dos cases seguintes.","Gerar erro obrigatório.","Converter a variável em boolean.","Executar apenas seu próprio rótulo sempre."]'::jsonb, 1, 'A passagem para os cases seguintes é chamada fall-through.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.6, páginas 165–168 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('68eddb4f-73c5-5f29-a25b-da149f01a284', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Linguagem de Programação', 'Médio', 'No switch tradicional Java SE 8, qual tipo não é admitido como seletor?', '["double.","String.","int.","Um tipo enum.","char."]'::jsonb, 0, 'A seleção múltipla tradicional não aceita double.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.6, páginas 165–168 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4da67863-cb89-53fd-afa8-407464bf801c', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Linguagem de Programação', 'Médio', 'Java SE 8 admite String em switch?', '["Somente com arrays.","Não, somente int.","Sim, mas apenas por identidade de referência.","Sim, comparando os valores textuais dos cases.","Não, String é primitivo."]'::jsonb, 3, 'Os rótulos precisam respeitar as regras de constantes e tipos do switch.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.7, páginas 169–171 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ca172c57-9153-5498-8ba7-2cac4e75458f', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Linguagem de Programação', 'Médio', 'Um break sem rótulo dentro de um loop encerra:', '["Somente a expressão seguinte.","Todos os loops aninhados.","Sempre toda a JVM.","O método obrigatoriamente.","O loop ou switch envolvente mais próximo aplicável."]'::jsonb, 4, 'O alcance do desvio depende da estrutura envolvente.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.8, páginas 172 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b2582520-7a8a-5604-8b93-5ecbd9153509', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Linguagem de Programação', 'Médio', 'Um continue sem rótulo em um for transfere o controle para:', '["O início do arquivo.","A inicialização do contador novamente.","A criação de outra thread.","A etapa de atualização, seguida de novo teste.","O fim obrigatório do método."]'::jsonb, 3, 'Continue abandona o restante da iteração corrente.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.8, páginas 172 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('79349293-4afa-5b52-a4a9-faf7cc89f91d', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Linguagem de Programação', 'Médio', 'Qual soma resulta ao somar 1 a 4, ignorando 2 com continue?', '["2.","10.","4.","8.","6."]'::jsonb, 3, 'Somam-se 1, 3 e 4.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.8, páginas 172 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7090c856-44fc-5189-bacc-ae746925a653', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Linguagem de Programação', 'Médio', 'Um loop percorre i=1,2,3,4 e faz break antes de somar 3. Qual soma de i anteriores?', '["6.","4.","3.","0.","10."]'::jsonb, 2, 'O break impede processar 3 e os valores posteriores.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.8, páginas 172 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ba532797-1c8a-5c13-84da-6f51c2710dfe', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Linguagem de Programação', 'Médio', 'O operador && usa curto-circuito quando o operando esquerdo é:', '["false.","true obrigatoriamente.","Sempre avalia ambos.","Um inteiro.","Uma String."]'::jsonb, 0, 'Uma conjunção já é falsa se o primeiro operando for falso.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.9, páginas 173–177 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9a53ad7d-2f88-5702-b989-4b13e20ecd85', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Linguagem de Programação', 'Médio', 'A disjunção condicional deixa de avaliar a direita quando a esquerda é:', '["false.","null obrigatoriamente.","true.","Zero.","Um char."]'::jsonb, 2, 'Um operando verdadeiro já determina a disjunção condicional.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.9, páginas 173–177 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ada298d3-f7e6-551d-bbe8-3d2c770dec35', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Linguagem de Programação', 'Médio', 'Qual resultado de `!true`?', '["Erro.","null.","0 como int.","true.","false."]'::jsonb, 4, 'A negação booleana inverte o valor lógico.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.9, páginas 173–177 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4f2c9a2d-2448-517b-9847-8a44b6d91708', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Linguagem de Programação', 'Médio', 'Qual resultado de `true ^ true` com operandos booleanos?', '["false.","Erro.","null.","1 como int.","true."]'::jsonb, 0, 'O OU exclusivo é verdadeiro quando os operandos diferem.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.9, páginas 173–177 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('034354e5-9cad-5be6-ae1d-a430af77ba90', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Linguagem de Programação', 'Médio', 'Em `x!=0 && 10/x>2`, com x=0, ocorre divisão por zero?', '["A expressão não compila.","Sim, mas o erro é ignorado.","Sim, sempre.","Somente no último loop.","Não, o segundo operando não é avaliado."]'::jsonb, 4, 'O curto-circuito protege a divisão nesse padrão.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 5, seção 5.9, páginas 173–177 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
